Read the article: ${article_url}` : t;

const email = [
  REDRAFT ? `Redraft ${ctx.round}. Your change: "${ctx.note}"` : '',
  failed ? 'THE REDRAFT FAILED, so this is the previous version. Pick Edit it to try again.' : '',
  `${plan.day} post (${plan.format}, ${words} words)`,
